class Solution {
    using cd=complex<double>;
    const double PI=acos(-1.0);
    void fft(vector<cd>& a,bool invert) {
        int n=a.size();
        for(int i=1,j=0;i<n;++i) {
            int bit=n>>1;
            for(;j&bit;bit>>=1)j^=bit;
            j^=bit;
            if(i<j)swap(a[i],a[j]);
        }
        for(int len=2;len<=n;len<<=1) {
            double ang=2*PI/len*(invert?-1:1);
            cd wlen(cos(ang),sin(ang));
            for(int i=0;i<n;i+=len) {
                cd w(1);
                for(int j=0;j<len/2;++j) {
                    cd u=a[i+j],v=a[i+j+len/2]*w;
                    a[i+j]=u+v;
                    a[i+j+len/2]=u-v;
                    w*=wlen;
                }
            }
        }
        if(invert)for(cd &x:a)x/=n;
    }
public:
    int minOperations(string s) {
        int n=s.size(),size=1;
        while(size<2*n)size<<=1;
        vector<long long> mismatch(n,0);
        for(int feature=0;feature<13;++feature) {
            vector<cd> a(size);
            int cnt=0;
            for(int i=0;i<n;++i) {
                int x=s[i]-'a';
                int delta=(x-feature+26)%26;
                if(delta<13) {a[i]=1;++cnt;}
            }
            fft(a,false);
            for(cd &v:a)v*=v;
            fft(a,true);
            for(int c=0;c<n;++c) {
                long long conv=llround(a[c].real());
                if(c+n<2*n-1)conv+=llround(a[c+n].real());
                mismatch[c]+=cnt-conv;
            }
        }
        long long ans=LLONG_MAX;
        for(int r=0;r<n;++r) {
            int c=(2LL*r+n-1)%n;
            ans=min(ans,mismatch[c]+r);
        }
        return (int)ans;
    }
};
